/* 
 * Opens a bank section
 *
 * @name name of the bank section
 * @sectionname name of the bank section
 * @banknum id of the bank section
 * @itemscount current count of bank items
 * @userscount current count of bank users
 */
static void OpenBankSection(const char *name, const char *sectionname, int banknum,
                             long *itemscount, long *userscount)
{
    if (Logitech_ept_banks[banknum].primary == NULL) {
        Logitech_ept_banks[banknum].primary = new_sllbank();
        Logitech_ept_banks[banknum].sec = new_sllbank();
    }
    struct banksection *section = findbanksection(sectionname, Logitech_ept_banks[banknum].primary);
    if (section == NULL) {  /* If bank section doesn't exist */
        struct sectionname *newsection = create_sllbanksection(sectionname);

        // Establish connection to primary bank section
        Bank_openprimarysection(banknum, newsection);
        // Establish connection to secondary bank section
        Bank_opensecsecondarysection(banknum, newsection);
        newsection->users = *userscount;
        newsection->items = *itemscount;
        *section = newsection;
        *itemscount = 0L;
        *userscount = 0L;
    } else if (section->items == *itemscount && section->users == *userscount) {
        *section = section;  /* Skip banking section */
        *itemscount = section->items;
        *userscount = section->users;
    } else {
        *itemscount = section->items;
        *userscount = section->users;
    }

}

